<?php
require __DIR__.'/../includes/bootstrap.php'; require_admin($conn);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=post_string('status');if(in_array($status,['active','blocked'],true)&&$id!==(int)current_user()['id']){$st=$conn->prepare("UPDATE users SET status=? WHERE id=? AND role='user'");$st->bind_param('si',$status,$id);$st->execute();flash('success','Customer status updated.');}redirect('admin/customers.php');}
$users=$conn->query("SELECT id,name,email,status,created_at FROM users WHERE role='user' ORDER BY created_at DESC")->fetch_all(MYSQLI_ASSOC);$pageTitle='Customers';require __DIR__.'/../includes/header.php';?>
<section class="page-hero"><div class="container"><p class="eyebrow">ADMINISTRATION</p><h1>Customer <em>accounts.</em></h1></div></section><section class="container section"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Joined</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e(date('d M Y',strtotime($u['created_at'])))?></td><td><?=e($u['status'])?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$u['id']?>"><select name="status"><option value="active" <?=$u['status']==='active'?'selected':''?>>Active</option><option value="blocked" <?=$u['status']==='blocked'?'selected':''?>>Blocked</option></select><button class="text-link">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>